import tensorflow as tf

class LSTMCell(tf.nn.rnn_cell.RNNCell):
    def __init__(self, num_units):
        self.units = num_units
        self.w_ih = tf.Variable(tf.random_normal([num_units, num_units]))
        self.w_hh = tf.Variable(tf.random_normal([num_units, num_units]))
        self.w_x = tf.Variable(tf.random_normal([num_units, num_units]))
        self.b = tf.Variable(tf.random_normal([num_units]))
        self.w_cell = tf.Variable(tf.random_normal([num_units, num_units]))
        self.w_oh = tf.Variable(tf.random_normal([num_units, num_units]))
        self.u1 = tf.Variable(tf.random_normal([num_units, num_units]))
        self.u2 = tf.Variable(tf.random_normal([num_units, num_units]))
        self.v = tf.Variable(tf.random_normal([num_units]))

    def call(self, x, h, c):
        gates = tf.tanh(tf.matmul(x, self.w_ih) + tf.matmul(h, self.w_hh) + self.w_x)
        c_new = tf.matmul(gates, self.w_cell) + self.b
        h_new = tf.matmul(gates, self.w_oh) + tf.tanh(c_new)
        return h_new, c_new

# Create a new LSTM cell with 128 units
lstm_cell = LSTMCell(128)

# Create a dummy input tensor
x = tf.random.normal([1, 10, 128])

# Create dummy initial state
h = tf.zeros((1, 128))
c = tf.zeros((1, 128))

# Run the LSTM
for i in range(10):
    h, c = lstm_cell(x[:, i, :], h, c)
```

