    units: u32,
    w_ih: [[f64; units]; units],
    w_hh: [[f64; units]; units],
    w_x: [[f64; units]; units],
    b: [f64; units],
    w_cell: [[f64; units]; units],
    w_oh: [[f64; units]; units],
    u1: [[f64; units]; units],
    u2: [[f64; units]; units],
    v: [f64; units],
}

impl LSTMCell {
    fn new(units: u32) -> LSTMCell {
        LSTMCell {
            units,
            w_ih: [[0.0; units]; units],
            w_hh: [[0.0; units]; units],
            w_x: [[0.0; units]; units],
            b: [0.0; units],
            w_cell: [[0.0; units]; units],
            w_oh: [[0.0; units]; units],
            u1: [[0.0; units]; units],
            u2: [[0.0; units]; units],
            v: [0.0; units],
        }
    }

    fn call(&self, x: &[[f64; 128]], h: &[[f64; 128]], c: &[[f64; 128]]) -> ([[f64; 128], [f64; 128]]) {
        let gates = self.w_ih.iter().map(|row| x.iter().map(|&val| val * row).sum::<f64>()).collect::<Vec<_>>();
        let gates = gates.iter().map(|&val| val + self.w_hh.iter().map(|row| h.iter().map(|&val| val * row).sum::<f64>()).sum::<f64>()).collect::<Vec<_>>();
        let gates = gates.iter().map(|&val| val + self.w_x.iter().map(|row| x.iter().map(|&val| val * row).sum::<f64>()).sum::<f64>()).collect::<Vec<_>>();
        let c_new = self.w_cell.iter().map(|row| gates.iter().map(|&val| val * row).sum::<f64>()).sum::<f64>();
        let h_new = self.w_oh.iter().map(|row| gates.iter().map(|&val| val * row).sum::<f64>()).sum::<f64>();
        (h_new, c_new)
    }
}

