    let h = [[0.0; 128]; 1];
    let c = [[0.0; 128]; 1];
    for i in 0..10 {
        let (h_new, c_new) = lstm_cell.call(&x[i], &h, &c);
        h = h_new;
        c = c_new;
    }
}
